/**
 * AssessmentReportsTab.jsx
 *
 * The report versions for one assessment.
 *
 * ── THE REPORT IS AssessmentReportPage, NOT A FILE ────────────────────────
 * Worth stating plainly, because it is easy to look at this tab and conclude
 * the product has no reports.
 *
 * The report people actually read is /reports/assessments/:id — a rendered
 * page that fetches the live assessment and lays out sections, answers,
 * verdicts, scores, findings and the workflow sign-off chain. Its Print
 * button produces the PDF, client-side, from what is on screen. That is the
 * report, it works, and it always has.
 *
 * What THIS tab lists is the version history: the numbers frozen at each
 * generation — compliance, scores, risk rating, open counts — so v1 (before
 * remediation) can be compared with v2 (after). Every row links to the report
 * page, which is where the content lives.
 *
 * ── WHY NOT A "GENERATE REPORT" BUTTON ────────────────────────────────────
 * The header used to carry one. Versioning is AUTOMATIC. decrementAndMaybeReport fires generateReportInternal from
 * validate-remediation and from CloseIssueAction the instant the last open
 * remediation closes, and every call stamps a NEW version. So a button
 * labelled "Generate report" invites someone to create a v4 that is
 * byte-identical to v3, and then to wonder which of the two is the real one.
 *
 * What people want when they reach for that button is the report that already
 * exists. GET /v1/assessments/{id}/reports returns the list of versions — each
 * with a version number, when it was stamped, what triggered it, the
 * compliance percentage and risk rating frozen at that moment, and a presigned
 * download URL. A list is not something a header button can render, so the
 * header action navigates here instead.
 *
 * ── THE SNAPSHOT IS THE POINT ─────────────────────────────────────────────
 * Each version carries its OWN compliancePct and riskRating, taken when it was
 * generated — not the assessment's current numbers. That is the whole value of
 * versioning: v1 is what the vendor scored before remediation, v2 is what they
 * scored after. Showing the live figure against every row would erase exactly
 * the thing somebody opened this tab to see, so every number below comes from
 * the row, and the delta against the previous version is spelled out.
 *
 * ── DOWNLOAD URLS ARE PRESIGNED AND SHORT-LIVED ───────────────────────────
 * storageService.generateDownloadUrl is called per row at request time, so the
 * URLs in a cached response expire. staleTime is deliberately short and the
 * link opens in a new tab rather than being fetched through axios — a
 * presigned S3 URL must not carry our Authorization header.
 *
 * A row whose document is not ACTIVE, or which has no s3Key, comes back with
 * downloadUrl: null. That is a real state (generation in flight, or an
 * archived version), and it renders as a disabled control that says so rather
 * than a link that 404s.
 */

import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  FileText, Download, Loader2, RefreshCcw, ShieldAlert, Clock, User,
  TrendingUp, TrendingDown, Minus, AlertTriangle,
} from 'lucide-react'
import { assessmentsApi } from '../../api/assessments.api'
import { cn } from '../../lib/cn'
import toast from 'react-hot-toast'
import { useStanding, P, unwrapList } from './vendorShared'

const RISK_TONE = {
  LOW:      'bg-status-pass-bg border-status-pass-bd text-status-pass-fg',
  MEDIUM:   'bg-status-warn-bg border-status-warn-bd text-status-warn-fg',
  HIGH:     'bg-status-fail-bg border-status-fail-bd text-status-fail-fg',
  CRITICAL: 'bg-status-fail-bg border-status-fail-bd text-status-fail-fg',
}

/**
 * The event that caused this version to be stamped. The backend writes these
 * into generatedData.triggerEvent; MANUAL is the only one a human causes.
 */
const TRIGGER_LABEL = {
  MANUAL:                 'Re-generated by hand',
  WORKFLOW_COMPLETE:      'Workflow completed',
  REMEDIATION_CLOSED:     'Last remediation closed',
  ALL_REMEDIATIONS_CLOSED:'All remediations closed',
}

function fmtWhen(v) {
  if (!v) return null
  try {
    const d = new Date(v)
    if (Number.isNaN(d.getTime())) return null
    return d.toLocaleString(undefined, {
      day: 'numeric', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit',
    })
  } catch { return null }
}

const pctOf = (r) => {
  const v = r?.compliancePct
  return typeof v === 'number' ? Math.round(v) : null
}

/** Change against the previous version. Null when there is nothing to compare. */
function Delta({ current, previous }) {
  if (current == null || previous == null) return null
  const d = current - previous
  if (d === 0) {
    return (
      <span className="inline-flex items-center gap-0.5 text-[9px] text-text-muted">
        <Minus size={8} /> no change
      </span>
    )
  }
  const up = d > 0
  return (
    <span className={cn('inline-flex items-center gap-0.5 text-[9px] font-medium',
      up ? 'text-status-pass-fg' : 'text-status-fail-fg')}>
      {up ? <TrendingUp size={8} /> : <TrendingDown size={8} />}
      {up ? '+' : ''}{d} pt{Math.abs(d) === 1 ? '' : 's'}
    </span>
  )
}

function ReportRow({ report, previous, isLatest, assessmentId, navigate }) {
  const pct = pctOf(report)
  const prevPct = pctOf(previous)
  const when = fmtWhen(report.generatedAt)
  const trigger = TRIGGER_LABEL[report.triggerEvent] || report.triggerEvent

  return (
    <div className={cn(
      'flex items-start gap-3 px-4 py-3 border-b border-border-subtle last:border-b-0',
      isLatest && 'bg-brand-500/[0.04]')}>

      <div className={cn(
        'w-9 h-9 rounded-card flex items-center justify-center shrink-0 border',
        isLatest ? 'bg-brand-500/10 border-brand-500/30 text-brand-ink'
                 : 'bg-surface-overlay border-border text-text-muted')}>
        <FileText size={15} />
      </div>

      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-xs font-semibold text-text-primary">
            Version {report.reportVersion ?? '—'}
          </span>
          {isLatest && (
            <span className="text-[9px] font-medium px-1.5 py-0.5 rounded bg-brand-500/15 text-brand-ink">
              Current
            </span>
          )}
          {report.riskRating && (
            <span className={cn('text-[9px] font-semibold px-1.5 py-0.5 rounded border',
              RISK_TONE[report.riskRating] || 'bg-surface-overlay border-border text-text-muted')}>
              {report.riskRating}
            </span>
          )}
          {pct != null && (
            <span className="text-[10px] font-mono text-text-secondary">{pct}% compliant</span>
          )}
          <Delta current={pct} previous={prevPct} />
        </div>

        <div className="flex items-center gap-3 mt-1 flex-wrap">
          {when && (
            <span className="inline-flex items-center gap-1 text-[10px] text-text-muted">
              <Clock size={9} /> {when}
            </span>
          )}
          {report.generatedByName && (
            <span className="inline-flex items-center gap-1 text-[10px] text-text-muted">
              <User size={9} /> {report.generatedByName}
            </span>
          )}
          {trigger && (
            <span className="text-[10px] text-text-muted">{trigger}</span>
          )}
        </div>

        {/* The two counts that were open when the version was stamped. They are
            the reason a v1 and a v2 differ, so they belong on the row rather
            than only on the assessment header, where they show TODAY's value. */}
        {(report.openRemediationCount > 0 || report.openClarificationCount > 0) && (
          <div className="flex items-center gap-2 mt-1 flex-wrap">
            {report.openRemediationCount > 0 && (
              <span className="inline-flex items-center gap-1 text-[9px] px-1.5 py-0.5 rounded bg-status-warn-bg text-status-warn-fg">
                <ShieldAlert size={8} />
                {report.openRemediationCount} remediation
                {report.openRemediationCount === 1 ? '' : 's'} open at the time
              </span>
            )}
            {report.openClarificationCount > 0 && (
              <span className="text-[9px] px-1.5 py-0.5 rounded bg-surface-overlay text-text-muted">
                {report.openClarificationCount} clarification
                {report.openClarificationCount === 1 ? '' : 's'} open
              </span>
            )}
          </div>
        )}

        {report.remarks && (
          <p className="mt-1 text-[10px] text-text-muted italic">“{report.remarks}”</p>
        )}
      </div>

      <div className="shrink-0 pt-0.5 flex items-center gap-1.5">
        {/* The report itself. AssessmentReportPage renders the live assessment
            and owns the Print-to-PDF path, so this is where someone goes to
            READ a report — the row beside it is the frozen numbers. */}
        <button
          type="button"
          onClick={() => navigate(`/reports/assessments/${assessmentId}`)}
          className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-ctl border border-brand-500/30 bg-brand-500/10 text-[11px] font-medium text-brand-ink hover:bg-brand-500/20 transition-colors">
          <FileText size={11} /> Open report
        </button>
        {report.downloadUrl ? (
          // Opened directly rather than fetched: the URL is presigned, and
          // sending it through axios would attach our Authorization header,
          // which S3 rejects as a conflicting signature.
          <a
            href={report.downloadUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-ctl border border-border text-[11px] font-medium text-text-secondary hover:bg-surface-overlay hover:text-text-primary transition-colors">
            <Download size={11} /> Download
          </a>
        ) : (
          // "No PDF", not "Unavailable".
          //
          // Unavailable implies something went wrong with THIS version. Nothing
          // did — the numbers on this row are real and final. What is missing
          // is a PDF renderer, which does not exist anywhere in the codebase:
          // both generation paths build `new byte[0]` and are commented as
          // stubs. Saying "unavailable" sends someone looking for a broken file
          // instead of telling them the truth, which is that the report is the
          // record and the document is not written yet.
          <span
            title="The report data is recorded. No PDF file is produced yet — a PDF generator is not wired into this build."
            className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-ctl border border-dashed border-border text-[11px] text-text-muted">
            <FileText size={11} /> No PDF
          </span>
        )}
      </div>
    </div>
  )
}

export default function AssessmentReportsTab({ assessmentId, entity, vc = {} }) {
  const qc = useQueryClient()
  const navigate = useNavigate()
  const standing = useStanding(vc, 'EVALUATE')
  const [regenerating, setRegenerating] = useState(false)

  const { data: raw, isLoading, isError, error } = useQuery({
    queryKey: ['assessment-reports', assessmentId],
    queryFn:  () => assessmentsApi.vendor.reports(assessmentId),
    enabled:  !!assessmentId,
    // Short, because every row carries a presigned URL that expires. A long
    // staleTime would hand out dead download links from cache.
    staleTime: 60 * 1000,
    retry: false,
  })

  // Newest first. The backend returns them in link order, which is insertion
  // order, and "which is the current report" is the first question anyone asks.
  const reports = useMemo(() => {
    const list = unwrapList(raw)
    return [...list].sort((a, b) => (b.reportVersion ?? 0) - (a.reportVersion ?? 0))
  }, [raw])

  const regenerate = useMutation({
    mutationFn: () => assessmentsApi.vendor.generateReport(assessmentId, ''),
    onSuccess: () => {
      toast.success('A new report version has been stamped')
      qc.invalidateQueries({ queryKey: ['assessment-reports', assessmentId] })
      qc.invalidateQueries({ queryKey: ['module-detail'] })
    },
    onError: (e) =>
      toast.error(e?.response?.data?.error?.message || e?.message || 'Could not generate the report'),
    onSettled: () => setRegenerating(false),
  })

  if (isLoading) return (
    <div className="flex items-center gap-2 px-4 py-8 text-[11px] text-text-muted">
      <Loader2 size={12} className="animate-spin" /> Loading reports…
    </div>
  )

  if (isError) return (
    <div className="flex items-start gap-2 px-4 py-6">
      <AlertTriangle size={13} className="text-status-fail-fg mt-0.5 shrink-0" />
      <p className="text-[11px] text-status-fail-fg">
        {error?.message || 'Could not load the report versions.'}
      </p>
    </div>
  )

  // Manual re-generation stays available to org-side reviewers only. It is a
  // recovery path — scores corrected after the last remediation closed — not
  // the normal way a report comes into existence.
  const canRegenerate = standing.can(P.FINDINGS_EDIT)

  return (
    <div>
      <div className="flex items-center gap-2 px-4 py-2.5 border-b border-border bg-surface-overlay/40 flex-wrap">
        <FileText size={11} className="text-text-muted shrink-0" />
        <span className="text-[11px] text-text-secondary">
          {reports.length === 0
            ? 'No report has been generated yet'
            : `${reports.length} version${reports.length === 1 ? '' : 's'}`}
        </span>
        <span className="flex-1" />
        {canRegenerate && (
          <button
            type="button"
            disabled={regenerating}
            onClick={() => {
              if (!window.confirm(
                'Stamp a new report version from the current scores? The previous version is kept.'
              )) return
              setRegenerating(true)
              regenerate.mutate()
            }}
            className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-ctl border border-border text-[11px] font-medium text-text-secondary hover:bg-surface-overlay hover:text-text-primary transition-colors disabled:opacity-50 disabled:cursor-wait">
            {regenerating
              ? <Loader2 size={11} className="animate-spin" />
              : <RefreshCcw size={11} />}
            Re-generate
          </button>
        )}
      </div>

      {reports.length === 0 ? (
        <div className="px-4 py-10 text-center">
          <FileText size={22} className="mx-auto text-text-muted mb-2" strokeWidth={1.5} />
          <p className="text-[11px] text-text-muted max-w-sm mx-auto leading-relaxed">
            No report VERSION has been stamped yet — versions are snapshots of the
            numbers, taken when the workflow completes and each time the last open
            remediation closes.
          </p>
          <button
            type="button"
            onClick={() => navigate(`/reports/assessments/${assessmentId}`)}
            className="mt-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-ctl border border-brand-500/30 bg-brand-500/10 text-[11px] font-medium text-brand-ink hover:bg-brand-500/20 transition-colors">
            <FileText size={11} /> Open the report
          </button>
          <p className="mt-2 text-[10px] text-text-muted">
            The report itself reads live and is available now.
          </p>
          {/* Worth saying, because an empty list here USED to mean something
              else entirely: versions were only recorded when a PDF existed, and
              no PDF generator exists, so a completed workflow produced an empty
              Reports tab and the header's Generate button answered 409. Both
              are fixed; an empty list now genuinely means nothing has run. */}
        </div>
      ) : (
        <div>
          {reports.map((r, i) => (
            <ReportRow
              key={r.linkId ?? r.documentId ?? i}
              report={r}
              // Versions are sorted newest-first, so the PREVIOUS version is
              // the next element, not the one before it.
              previous={reports[i + 1]}
              isLatest={i === 0}
              assessmentId={assessmentId}
              navigate={navigate}
            />
          ))}
        </div>
      )}
    </div>
  )
}